import {saveStore,decodeSave,encodeSave} from './save-game.js';
export function persistence({snapshot,restore,isStarted,onReset,disabled=false}){
const status=document.querySelector('#save-status'),indicator=document.querySelector('#save-indicator'),start=document.querySelector('#start');let store,loaded=false,lastSignature='',since=0,sample=0,flash;const initial=snapshot();
function report(message,error=false){status.textContent=message;status.classList.toggle('save-error',error);indicator.textContent=message;indicator.classList.toggle('save-error',error);clearTimeout(flash);flash=setTimeout(()=>indicator.textContent='',4000)}
try{if(!disabled)store=saveStore(localStorage)}catch{report('Браузер запретил доступ к сохранениям. Используйте экспорт в файл.',true)}
function signature(s){return JSON.stringify([s.chapter.p,s.dungeon?.mode,s.dungeon?.boss?.hp,s.dungeon?.chests,s.chapter.ritual,s.ritual?.mode,s.ritual?.mirror?.actor.hp,s.chapter.combat?.rank,s.chapter.combat?.mageShots,s.world.troll?.actor.hp,s.world.troll?.serial,s.chapter.slots,s.chapter.chest,s.player.vitals.maxHp,s.player.vitals.maxStamina,s.player.vitals.maxMana,s.player.vitals.hp<=0,s.world.inside,s.cemetery?.inside,s.cemetery?.mobs.map(a=>[a.hp,a.generation]),s.cemetery?.drops.length,s.world.hunter?.hp,s.actors.map(a=>a.hp),s.world.mobs.map(a=>[a.hp,a.generation]),s.world.drops.map(d=>[d.id,d.position[0],d.position[2]]),[s.encounter.started,s.encounter.mobs.map(a=>a.hp)]])}
function save(){if(disabled||!isStarted())return false;try{if(!store)throw new Error();const state=snapshot();store.write(state);loaded=true;lastSignature=signature(state);since=0;report('Сохранено · '+new Date().toLocaleTimeString('ru-RU',{hour:'2-digit',minute:'2-digit'}));return true}catch{report('Не удалось сохранить в браузере. Экспортируйте сохранение в файл.',true);return false}}
function ask(message,action){const box=document.querySelector('#save-confirm');box.hidden=false;box.querySelector('p').textContent=message;box.querySelector('[data-confirm]').onclick=()=>{box.hidden=true;action()};box.querySelector('[data-cancel]').onclick=()=>box.hidden=true}
if(store){try{const result=store.read();if(result.data){restore(result.data);loaded=true;lastSignature=signature(result.data);start.textContent='ПРОДОЛЖИТЬ';report(result.backup?'Основное сохранение повреждено. Восстановлена резервная копия.':'Сохранение найдено · '+new Date(result.data.savedAt).toLocaleString('ru-RU'))}else if(result.corrupt)report('Сохранение повреждено. Можно импортировать резервный файл или начать новую игру.',true);else status.textContent='Прогресс будет сохраняться автоматически.'}catch{report('Не удалось прочитать сохранение. Доступен импорт из файла.',true)}}
document.querySelector('#new-game').onclick=()=>ask('Начать новую игру? Текущее прохождение и его локальная резервная копия будут заменены. При необходимости сначала экспортируйте сохранение.',()=>{try{store?.clear()}catch{report('Не удалось удалить старое сохранение. Новая игра не начата.',true);return}restore(initial);onReset();loaded=false;lastSignature='';since=0;start.textContent='ОЧНУТЬСЯ';report('Новая игра готова. Нажмите «Очнуться».')});
document.querySelector('#save-now').onclick=save;
document.querySelector('#export-save').onclick=()=>{try{if(!isStarted()&&!loaded){report('Сначала начните игру.',true);return}const raw=encodeSave(snapshot()),url=URL.createObjectURL(new Blob([raw],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download='hanskoy-save-'+new Date().toISOString().slice(0,19).replaceAll(':','-')+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);report('Сохранение экспортировано в файл.')}catch{report('Не удалось экспортировать сохранение.',true)}};
const input=document.querySelector('#import-file');document.querySelector('#import-save').onclick=()=>input.click();input.onchange=async()=>{const file=input.files?.[0];input.value='';if(!file)return;let data;try{if(file.size>2000000)throw new Error('Файл слишком большой.');data=decodeSave(await file.text())}catch{report('Файл не подходит или повреждён. Текущее прохождение не изменено.',true);return}ask('Загрузить выбранное сохранение вместо текущего прохождения?',()=>{restore(data);loaded=true;onReset();start.textContent='ПРОДОЛЖИТЬ';try{store?.write(data);lastSignature=signature(data);report(store?'Сохранение импортировано. Нажмите «Продолжить».':'Файл загружен, но хранение в браузере недоступно.',!store)}catch{report('Файл загружен. Автосохранение недоступно — используйте экспорт.',true)}})};
window.addEventListener('pagehide',save);window.addEventListener('beforeunload',save);document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='hidden')save()});
return {save,get loaded(){return loaded},tick(dt){if(disabled||!isStarted())return;since+=dt;sample+=dt;if(sample<.5)return;sample=0;const current=snapshot();if(signature(current)!==lastSignature||since>=30)save()}};
}
